INSERT INTO site_settings (key, value) VALUES ('tagline','Portraits & paintings from the heart of Jamshedpur — shipped worldwide'),('instagram','artbymukherjee'),('email','artbymukherjee@gmail.com'),('facebook','https://www.facebook.com/people/Deepshikha-Mukherjee/61579608390154/'),('whatsapp','+919123297198'),('aboutText','Deepshikha Mukherjee is a versatile fine artist residing in Jamshedpur, Jharkhand. She works with Oil , Acrylic, Charcoal, Watercolor, Graphite.
She was 4 years old when her parents noticed her sketching huge faces and human figures on the floor with chalk. To her parents'' surprise, her scribbling on the floor, unlike other children of her age, actually made sense. The same year, they got her admitted in Tagore School of Arts, Jamshedpur and there was no looking back. She pursued Fine Arts for almost 20 years along with her schooling and further education.'),('shippingCharge','500'),('priceGuide','Portrait — Charcoal / Graphite|From ₹2,500;Portrait — Oil / Acrylic|From ₹3,500'),('faqs','How long does a commission take?|Typically 3–6 weeks depending on size and medium.;Do you ship outside India?|Yes — professional packaging and insured worldwide shipping.;What advance is needed?|50% advance payment to confirm the commission.'),('turnaround','Typical turnaround 3–6 weeks. Final timeline is confirmed during consultation.'),('gatewayMode','Test Mode — Razorpay (keys in server environment only)'),('heroAsset','oilFloralPortrait'),('adminEmail','artwithmukherjee@gmail.com'),('adminPassHash','$argon2id$v=19$m=65536,t=2,p=1$oKzjW8djs5ooa2PEujX4bLVZSRt7mUIs1ZW0yHwPdwg$bLl7gFf7FfV4Dd0njg+FOr5IC8FfVUMFzcZi0GxA/KM');
